1055	func (s *syncSession) runReplicate(ctx context.Context) (Result, error) {
1056		// An empty source advertisement is resolved BEFORE planning. Under AllRefs
1057		// the advertisement covers refs/, so "nothing advertised" is already a
1058		// complete observation and planning cannot add to it — while
1059		// BuildDesiredRefs errors on a mapping whose source ref is absent, which
1060		// on a genuinely empty source is every mapping. Deciding after planning
1061		// left the whole policy inert for any request that pinned refs by mapping:
1062		// the caller got "source ref X not found" matching no sentinel, on exactly
1063		// the state the policy exists to make succeed.
1064		//
1065		// Gated on the opt-in so a caller that never asked for this still gets the
1066		// planner's error verbatim.
1067		//
1068		// The relay check runs FIRST, above both this intercept and planning. It is
1069		// a property of the target, not of the work: replicate refuses a non-relay
1070		// target outright, and a converged result claims Relay: true on the
1071		// strength of that refusal. Deciding emptiness ahead of it would let the
1072		// one path that makes the claim be the one path that never checked it.
1073		if ok, reason := planner.SupportsReplicateRelay(s.target.policy); !ok {
1074			return Result{OperationMode: modeReplicate}, fmt.Errorf("replicate requires relay-capable target: %s; use sync instead", reason)
1075		}
1076		if s.cfg.AllowEmptySource && s.cfg.AllRefs && len(s.sourceRefMap) == 0 {
1077			return s.resolveEmptySource()
1078		}
1079		desiredRefs, managedTargets, err := planner.BuildDesiredRefs(s.sourceRefMap, planConfig(s.cfg))
1080		if err != nil {
1081			return Result{}, fmt.Errorf("build desired refs: %w", err)
1082		}
1083		if len(desiredRefs) == 0 {
1084			return s.resolveEmptyDesiredSet()
1085		}
1086	
1087		allAbsent := s.replicateCanBootstrap(desiredRefs)
1088		if allAbsent {
1089			if s.cfg.DryRun {
1090				plans, err := planner.BuildBootstrapPlans(desiredRefs, s.target.refMap)
1091				if err != nil {
1092					return Result{}, fmt.Errorf("build bootstrap plans: %w", err)
1093				}
1094				return Result{
1095					Plans:              plans,
1096					DryRun:             true,
1097					OperationMode:      modeReplicate,
1098					RelayReason:        "empty-target-managed-refs",
1099					BootstrapSuggested: true,
1100					Stats:              s.stats.snapshot(),
1101					Measurement:        s.measurementDone(),
1102					Protocol:           s.sourceService.Protocol,
1103					SourceHEAD:         s.sourceService.HeadTarget,
1104				}, nil
1105			}
1106			return bootstrapWithInputs(ctx, s, desiredRefs, s.target.refMap, "empty-target-managed-refs")
1107		}
1108	
1109		plans, err := planner.BuildReplicationPlans(desiredRefs, s.target.refMap, managedTargets, planConfig(s.cfg))
1110		if err != nil {
1111			return Result{}, fmt.Errorf("build replication plans: %w", err)
1112		}
1113	
1114		result := Result{
1115			Plans:         plans,
1116			DryRun:        s.cfg.DryRun,
1117			OperationMode: modeReplicate,
1118			Protocol:      s.sourceService.Protocol,
1119			Stats:         s.stats.snapshot(),
1120			Measurement:   s.measurementDone(),
1121			SourceHEAD:    s.sourceService.HeadTarget,
1122		}
1123	
1124		pushPlans := classifyPlans(plans, s.cfg.DryRun, &result)
1125		relayPlans := make([]BranchPlan, 0, len(pushPlans))
1126		for _, plan := range pushPlans {
1127			if plan.Action != ActionDelete {
1128				relayPlans = append(relayPlans, plan)
1129			}
1130		}
1131	
1132		if !s.cfg.DryRun && len(pushPlans) > 0 {
1133			if len(relayPlans) > 0 {
1134				ok, reason := planner.CanReplicateRelay(relayPlans)
1135				if !ok {
1136					return result, fmt.Errorf("replicate requires relay-capable target: %s; use sync instead", reason)
1137				}
1138			}
1139			repResult, err := s.executeReplicate(ctx, desiredRefs, pushPlans)
1140			if err != nil {
1141				return result, fmt.Errorf("replicate relay failed: %w", err)
1142			}
1143			result.Relay = repResult.Relay
1144			result.RelayMode = repResult.RelayMode
1145			result.RelayReason = repResult.RelayReason
1146		}
1147	
1148		s.finalizeCounts(pushPlans, &result)
1149		if err := s.leaseFailureError(); err != nil {
1150			return result, err
1151		}
1152		result.Stats = s.stats.snapshot()
1153		result.Measurement = s.measurementDone()
1154		return result, nil
1155	}
