1237	// Fetch exercises source-side fetch negotiation.
1238	func Fetch(ctx context.Context, cfg Config, haveRefs []string, haveHashes []plumbing.Hash) (FetchResult, error) {
1239		if cfg.Source.URL == "" {
1240			return FetchResult{}, errors.New("source repository URL is required")
1241		}
1242	
1243		s, err := newSession(ctx, cfg, false)
1244		if err != nil {
1245			return FetchResult{}, err
1246		}
1247		defer s.finish()
1248	
1249		// Bounded only when the caller asks, with no default — unlike the sync path
1250		// above. Fetch exists to exercise source-side negotiation and, without
1251		// --have, deliberately pulls a full pack, so a default ceiling would fail a
1252		// previously working operation at the limit. The sync path's fetch is
1253		// have-bounded by the target's refs, so there the cap tracks the diff being
1254		// pushed, which is what the limit is for.
1255		repo, err := git.Init(newBoundedStorer(memory.NewStorage(), cfg.MaterializedMaxObjects), nil)
1256		if err != nil {
1257			return FetchResult{}, fmt.Errorf("init in-memory repository: %w", err)
1258		}
1259		desiredRefs, err := s.buildDesiredRefs()
1260		if err != nil {
1261			return FetchResult{}, fmt.Errorf("build desired refs: %w", err)
1262		}
1263		targetRefMap, err := s.buildHaveRefMap(haveRefs, haveHashes)
1264		if err != nil {
1265			return FetchResult{}, fmt.Errorf("build have ref map: %w", err)
1266		}
1267	
1268		gpDesired := convert.DesiredRefs(desiredRefs)
1269		if err := s.sourceService.FetchToStore(ctx, repo.Storer, s.sourceConn, gpDesired, targetRefMap); err != nil {

880			s.target.pusher = gitproto.NewPusher(targetConn, targetAdv, cfg.Verbose)
881			s.target.pusher.MaxRefUpdates = cfg.TargetMaxRefUpdates
882			if cfg.BestEffort {
883				s.rejections = make(map[plumbing.ReferenceName]string)
884				s.target.pusher.OnRejection = func(name plumbing.ReferenceName, status string) {
885					// Server-authored text that becomes BranchPlan.Reason, which is
886					// printed by FormatPlanLine and marshalled as "reason". This is
887					// the designed path under --all-refs, where per-ref rejections
888					// surface as warnings rather than errors, so it carries hostile
889					// text to the terminal and to --json by intent. It never passes
890					// through asRefRejectedError, so filtering has to happen here.
891					// IsLeaseFailure and applyRejections only substring-match, so
892					// this cannot change how a rejection is classified.
893					s.rejections[name] = sanitize.Text(status)
894				}
895			}
896		}
897		// Start the live progress ticker only after auth resolution and the
898		// initial ref-listing round trips have completed. The auth path may
899		// shell out to `git credential fill`, which inherits our stderr and
900		// can prompt the user; an interactive prompt and a '\r'-redrawing
901		// ticker writing to the same tty would clobber each other. Deferring
902		// the ticker until newSession returns guarantees no concurrent writer
903		// is active when prompts happen and also avoids leaking a goroutine
904		// when newSession fails partway through setup.
905		if cfg.Progress {
906			out := cfg.progressOut
907			if out == nil {
908				out = os.Stderr
909			}
910			// Render only when the destination is a real terminal. Pipes,
911			// log files, and CI captures get nothing rather than a flood
912			// of '\r'-prefixed control sequences.
913			if out != os.Stderr || stderrIsTTY() {
914				s.progress = newProgressReporter(out, s.stats, 0)
915				go s.progress.run()
916			}
917		}
918	
919		success = true
920		return s, nil
921	}
