959				}
960				return Result{
961					Plans: plans, DryRun: true, RelayReason: reason,
962					OperationMode: modeSync, BootstrapSuggested: true, Stats: stats.snapshot(),
963					Measurement: measurementDone(), Protocol: sourceService.Protocol,
964					SourceHEAD: s.sourceService.HeadTarget,
965				}, nil
966			}
967			return bootstrapWithInputs(ctx, s, desiredRefs, targetRefMap, reason)
968		}
