971		// lazily — only when planning needs ancestry data (FF detection on a
972		// divergent branch) or when the materialized fallback ends up running.
973		// Pure skip/create plans that take incremental relay never decode
974		// source objects locally, so the upfront fetch would be a wasted
975		// full-pack round trip.
976		// Bound the store before anything is fetched into it: the object limit used
977		// to be checked on the closure afterwards, which cannot prevent the memory
978		// growth it exists to prevent.
979		repo, err := git.Init(newBoundedStorer(memory.NewStorage(), effectiveMaxObjects(s.cfg)), nil)
980		if err != nil {
981			return Result{}, fmt.Errorf("init in-memory repository: %w", err)
982		}
983		gpDesired := convert.DesiredRefs(desiredRefs)
984		closureFetched := false
985		fetchClosure := func() error {
986			if closureFetched {
987				return nil
988			}
989			if err := sourceService.FetchToStore(ctx, repo.Storer, s.sourceConn, gpDesired, targetRefMap); err != nil {
990				if !errors.Is(err, git.NoErrAlreadyUpToDate) {
991					return fmt.Errorf("fetch to store: %w", err)
992				}
993			}
994			closureFetched = true
995			return nil
996		}
997		if needsLocalSourceClosure(s.cfg, desiredRefs, targetRefMap) {
998			if err := fetchClosure(); err != nil {
999				return Result{}, err
1000			}
1001		}
1002	
1003		plans, err := planner.BuildPlans(repo.Storer, desiredRefs, targetRefMap, managedTargets, planConfig(s.cfg))
1004		if err != nil {
1005			return Result{}, fmt.Errorf("build plans: %w", err)
1006		}
1007	
1008		result := Result{
1009			Plans: plans, DryRun: s.cfg.DryRun, OperationMode: modeSync, Protocol: sourceService.Protocol,
1010			Stats: stats.snapshot(), Measurement: measurementDone(),
1011			SourceHEAD: s.sourceService.HeadTarget,
1012		}
1013	
1014		pushPlans := classifyPlans(plans, s.cfg.DryRun, &result)
1015	
1016		if !s.cfg.DryRun && result.Blocked > 0 {
1017			return result, fmt.Errorf("blocked %d ref update(s); rerun with --force-with-lease (or --force-blind) where appropriate", result.Blocked)
