1020	
1021		if !s.cfg.DryRun {
1022			// Try incremental relay first
1023			incResult, err := s.executeIncremental(ctx, desiredRefs, pushPlans)
1024			if err != nil {
1025				return result, err
1026			}
1027			if incResult.Relay {
1028				result.Relay = incResult.Relay
1029				result.RelayMode = incResult.RelayMode
1030				result.RelayReason = incResult.RelayReason
1031			} else if len(pushPlans) > 0 {
1032				// Materialized fallback. needsLocalSourceClosure may have skipped
1033				// the upfront fetch when relay looked eligible from the plan
1034				// shape alone, but CanIncrementalRelay can still reject (e.g.
1035				// when target capabilities are unknown). Fetch on demand so
1036				// materialized doesn't run against an empty store.
