560								"calibration_denom", calibrationDenom,
561								"object_count", packObjectCount,
562								"objects_sent", objectsSent)
563							calibratedBytesPerObject = updated
564						}
565						selfImposedBudget = nextSelfImposedBudget(selfImposedBudget, parsedLimit, sentBytes, abortedEarly)
566						// Pick the byte count we use for sizing the next
567						// subdivision. When the server cut us off, sentBytes
568						// is roughly the cap and using it directly is right.
569						// When *we* cut the upload early, sentBytes is just
570						// the abort point (~minBytesBeforeAbort) — much less
571						// than the real pack size — so the factor would
572						// converge slowly. Project from observed bytes/object
573						// to the full pack size when we have the data, so
574						// factor reflects the real overshoot.
575						sizingBytes := sentBytes
576						if abortedEarly && totalObjects > 0 && effObjectsSent > 0 {
577							if projected := sentBytes * totalObjects / effObjectsSent; projected > sizingBytes {
578								sizingBytes = projected
579							}
580						}
581						factor := observedSubdivisionFactor(sizingBytes, limit)
582						expanded := subdivideToFactor(batch.chain, current, batch.Checkpoints[idx:], factor)
583						if len(expanded) > len(batch.Checkpoints[idx:]) {
584							oldRemaining := len(batch.Checkpoints[idx:])
585							newCount := len(expanded)
586							p.log("bootstrap batch subdividing after target size rejection",
587								"branch", batch.Plan.TargetRef.String(),
588								"old_remaining", oldRemaining,
589								"new_remaining", newCount,
590								"sent_bytes", sentBytes,
591								"sizing_bytes", sizingBytes,
592								"limit_bytes", limit,
593								"factor", factor,
594								"aborted_early", abortedEarly,
595								"error", pushErr.Error())
596							limitText := ""
597							if limit > 0 {
598								limitText = fmt.Sprintf(" (target limit %s)", gitproto.HumanBytes(limit))
599							}
600							reason := "target rejected pack"
601							if abortedEarly {
602								reason = "projected to exceed target limit"
603							}
604							p.notice(fmt.Sprintf("%s%s — splitting %d → %d packs",
605								reason, limitText, oldRemaining, newCount))
606							batch.Checkpoints = append(batch.Checkpoints[:idx], expanded...)
607							continue // retry at same idx with new (smaller) checkpoint
608						}
609					}
610					return result, fmt.Errorf("push bootstrap batch for %s: %w", batch.Plan.TargetRef, pushErr)
611				}
612				_ = packReader.Close()
613				p.log("bootstrap batch checkpoint complete",
614					"branch", batch.Plan.TargetRef.String(),
615					"batch", idx+1,
616					"batch_total", len(batch.Checkpoints))
617				current = checkpoint
618				pushedCheckpoints = append(pushedCheckpoints, checkpoint)
619				result.BatchCount++
620	
621				// Recombine: subdivision is a one-way ratchet, so the fine
622				// granularity needed for one heavy commit sticks around for
623				// the rest of the chain even when the deltas afterward are
624				// tiny. Aim for the next pack to be roughly half the target
625				// limit by dropping enough checkpoints that the span doubles
626				// approximately log2(target/2 / sent) times. If we
627				// overshoot, the abort-early + subdivision path re-splits.
628				// Leave at least the final checkpoint after idx (it carries
629				// the SourceHash cutover), so the cap is len-idx-2.
630				if dropCount := recombineDropCount(sentBytes, p.TargetMaxPack, len(batch.Checkpoints)-idx-2); dropCount > 0 {
631					dropped := batch.Checkpoints[idx+1]
632					batch.Checkpoints = append(batch.Checkpoints[:idx+1], batch.Checkpoints[idx+1+dropCount:]...)
633					p.log("bootstrap batch recombining after small push",
634						"branch", batch.Plan.TargetRef.String(),
635						"sent_bytes", sentBytes,
636						"target_limit_bytes", p.TargetMaxPack,
637						"dropped_count", dropCount,
638						"first_dropped_checkpoint", planner.ShortHash(dropped),
639						"remaining_checkpoints", len(batch.Checkpoints))
640				}
641				idx++
642			}
643	
644			if current.IsZero() {
645				return result, fmt.Errorf("bootstrap batching for %s completed with no checkpoint state", batch.Plan.TargetRef)
646			}
647			if batch.ResumeHash == batch.Plan.SourceHash && p.TargetRefs[batch.Plan.TargetRef].IsZero() {
648				cmds := []gitproto.PushCommand{{Name: batch.Plan.TargetRef, Old: plumbing.ZeroHash, New: batch.Plan.SourceHash}}
649				if err := p.TargetPusher.PushCommands(ctx, cmds); err != nil {
650					return result, fmt.Errorf("resume bootstrap cutover for %s: %w", batch.Plan.TargetRef, err)
651				}
652			}
653	
654			cmds := []gitproto.PushCommand{{Name: batch.TempRef, Old: current, Delete: true}}
655			if err := p.TargetPusher.PushCommands(ctx, cmds); err != nil {
656				return result, fmt.Errorf("delete bootstrap temp ref for %s: %w", batch.Plan.TargetRef, err)
657			}
658			completedRefs[batch.Plan.TargetRef] = batch.Plan.SourceHash
659			completedRefs[batch.TempRef] = batch.Plan.SourceHash
660			p.log("bootstrap batch branch finalized", "branch", batch.Plan.TargetRef.String())
661		}
662	
663		// Tail phase: tags and other-kind refs (issue #1)
664		if len(tailPlans) > 0 {
665			p.log("bootstrap batch pushing tail refs after branch batches", "tail_count", len(tailPlans))
666			if p.OnPhase != nil {
667				p.OnPhase(tailPhaseLabel(tailPlans))
668			}
669			tailTargetRefs := planner.CopyRefHashMap(p.TargetRefs)
670			for _, batch := range batches {
671				tailTargetRefs[batch.Plan.TargetRef] = batch.Plan.SourceHash
672			}
673			packReader, err := p.SourceService.FetchPack(ctx, p.SourceConn, tailDesired, tailTargetRefs)
674			if err != nil {
675				if errors.Is(err, git.NoErrAlreadyUpToDate) {
676					cmds := convert.PlansToPushCommands(tailPlans, false)
677					if err := p.TargetPusher.PushCommands(ctx, cmds); err != nil {
678						return result, fmt.Errorf("create tail refs after bootstrap: %w", err)
679					}
680				} else {
681					return result, fmt.Errorf("fetch bootstrap tail pack: %w", err)
682				}
683			} else {
684				packReader = gitproto.LimitPackReader(packReader, p.MaxPackBytes)
685				packReader = gitproto.CloseOnce(packReader)
686				cmds := convert.PlansToPushCommands(tailPlans, false)
687				if err := p.TargetPusher.PushPack(ctx, cmds, packReader); err != nil {
688					_ = packReader.Close()
689					return result, fmt.Errorf("push bootstrap tail refs: %w", err)
690				}
691				_ = packReader.Close()
692			}
693		}
694	
695		result.Pushed = len(plans)
696		result.Batching = true
697		result.RelayMode = "bootstrap-batch"
698		return result, nil
699	}
