724	
725	func planBatches(ctx context.Context, p Params, desired []planner.DesiredRef) ([]plannedBatch, error) {
726		ordered, trunkIdx := orderTrunkFirst(desired, p.SourceHeadTarget)
727		switch {
728		case p.SourceHeadTarget == "":
729			p.log("bootstrap batch trunk unset", "reason", "source did not advertise a HEAD symref")
730		case trunkIdx < 0:
731			p.log("bootstrap batch trunk unset",
732				"reason", "HEAD ref not in desired set (filtered by --branch or --map)",
733				"source_head_target", p.SourceHeadTarget.String())
734		default:
735			p.log("bootstrap batch trunk selected",
736				"source_head_target", p.SourceHeadTarget.String(),
737				"trunk_target_ref", ordered[trunkIdx].TargetRef.String())
738		}
739		out := make([]plannedBatch, 0, len(ordered))
740	
741		var (
742			trunkStopSet map[plumbing.Hash]struct{}
743			trunkHaves   []plumbing.Hash
744		)
745	
746		for i, ref := range ordered {
747			// Branches whose tip is already reachable from trunk's ancestry need
748			// no pack transfer — trunk's batches already delivered every object.
749			// Emit a subsumed batch that the executor handles with a single ref
750			// create command.
751			if i != trunkIdx && trunkStopSet != nil {
752				if _, subsumed := trunkStopSet[ref.SourceHash]; subsumed {
753					p.log("bootstrap batch branch subsumed by trunk",
754						"branch", ref.TargetRef.String(),
755						"source_hash", planner.ShortHash(ref.SourceHash))
756					out = append(out, plannedBatch{
757						BootstrapBatch: planner.BootstrapBatch{
758							Plan: planner.BranchPlan{
759								Branch: ref.Label, SourceRef: ref.SourceRef,
760								TargetRef: ref.TargetRef, SourceHash: ref.SourceHash,
761								Kind: ref.Kind, Action: planner.ActionCreate,
762							},
763						},
764						subsumed: true,
765					})
766					continue
767				}
768			}
769			var (
770				haves  []plumbing.Hash
771				stopAt map[plumbing.Hash]struct{}
772			)
773			if i != trunkIdx && trunkStopSet != nil {
774				haves = trunkHaves
775				stopAt = trunkStopSet
776			}
777			checkpoints, chain, ancestors, err := planCheckpointsFromChain(ctx, p, ref, haves, stopAt)
778			if err != nil {
779				return nil, err
780			}
781			if i == trunkIdx && trunkIdx >= 0 {
782				trunkStopSet = ancestors
783				trunkHaves = []plumbing.Hash{ref.SourceHash}
784			}
785			out = append(out, plannedBatch{
786				BootstrapBatch: planner.BootstrapBatch{
787					Plan: planner.BranchPlan{
788						Branch: ref.Label, SourceRef: ref.SourceRef,
789						TargetRef: ref.TargetRef, SourceHash: ref.SourceHash,
790						Kind: ref.Kind, Action: planner.ActionCreate,
791					},
792					TempRef:     planner.BootstrapTempRef(ref.TargetRef),
793					ResumeHash:  p.TargetRefs[planner.BootstrapTempRef(ref.TargetRef)],
794					Checkpoints: checkpoints,
795				},
796				chain: chain,
797			})
798		}
799		return out, nil
800	}
