802	// orderTrunkFirst returns desired reordered so the branch matching
803	// sourceHeadTarget is first. If no match, the original order is preserved and
804	// trunkIdx is -1. Otherwise trunkIdx is 0 (the position of the trunk).
805	func orderTrunkFirst(desired []planner.DesiredRef, sourceHeadTarget plumbing.ReferenceName) ([]planner.DesiredRef, int) {
806		if sourceHeadTarget == "" {
807			return desired, -1
808		}
809		reordered, idx := hoistFirstMatch(desired, func(r planner.DesiredRef) bool {
810			return r.SourceRef == sourceHeadTarget
811		})
812		if idx < 0 {
813			return desired, -1
814		}
815		return reordered, 0
816	}
