1	// Package replicate implements relay-only source-authoritative replication.
2	package replicate
3	
4	import (
5		"context"
6		"errors"
7		"fmt"
8		"io"
9	
10		"github.com/go-git/go-git/v6/plumbing"
11	
12		"entire.io/entire/git-sync/internal/convert"
13		"entire.io/entire/git-sync/internal/gitproto"
14		"entire.io/entire/git-sync/internal/planner"
15	)
16	
17	// Params holds the inputs for a replication relay execution.
18	type Params struct {
19		SourceConn    gitproto.Conn
20		SourceService interface {
21			FetchPack(ctx context.Context, conn gitproto.Conn, desired map[plumbing.ReferenceName]gitproto.DesiredRef, haves map[plumbing.ReferenceName]plumbing.Hash) (io.ReadCloser, error)
22		}
23		TargetPusher interface {
24			PushPack(ctx context.Context, cmds []gitproto.PushCommand, pack io.ReadCloser) error
25			PushCommands(ctx context.Context, cmds []gitproto.PushCommand) error
26		}
27		DesiredRefs  map[plumbing.ReferenceName]planner.DesiredRef
28		TargetRefs   map[plumbing.ReferenceName]plumbing.Hash
29		PushPlans    []planner.BranchPlan
30		MaxPackBytes int64
31	}
32	
33	// Result holds the outcome of a replication relay.
34	type Result struct {
35		Relay       bool
36		RelayMode   string
37		RelayReason string
38	}
39	
40	// Execute runs relay-only replication. Create/update refs are pushed via pack
41	// relay and deletes are sent afterwards as ref-only commands.
42	func Execute(ctx context.Context, p Params) (Result, error) {
43		if p.TargetPusher == nil {
44			return Result{}, errors.New("replicate strategy requires TargetPusher")
45		}
46	
47		updatePlans := make([]planner.BranchPlan, 0, len(p.PushPlans))
48		deletePlans := make([]planner.BranchPlan, 0, len(p.PushPlans))
49		for _, plan := range p.PushPlans {
50			switch plan.Action {
51			case planner.ActionCreate, planner.ActionUpdate:
52				updatePlans = append(updatePlans, plan)
53			case planner.ActionDelete:
54				deletePlans = append(deletePlans, plan)
55			case planner.ActionSkip, planner.ActionBlock, planner.ActionWarn:
56				// not applicable: replicate runs before any rejection downgrade,
57				// and skip/block plans never reach the executor.
58			}
59		}
60	
61		if len(updatePlans) > 0 {
62			desired := convert.DesiredRefsForPlans(p.DesiredRefs, updatePlans)
63			packReader, err := p.SourceService.FetchPack(ctx, p.SourceConn, desired, p.TargetRefs)
64			if err != nil {
65				return Result{}, fmt.Errorf("fetch source pack: %w", err)
66			}
67			packReader = gitproto.LimitPackReader(packReader, p.MaxPackBytes)
68			packReader = gitproto.CloseOnce(packReader)
69			if err := p.TargetPusher.PushPack(ctx, convert.PlansToPushCommands(updatePlans, false), packReader); err != nil {
70				_ = packReader.Close()
71				return Result{}, fmt.Errorf("push target refs: %w", err)
72			}
73			_ = packReader.Close()
74		}
75	
76		if len(deletePlans) > 0 {
77			if err := p.TargetPusher.PushCommands(ctx, convert.PlansToPushCommands(deletePlans, false)); err != nil {
78				return Result{}, fmt.Errorf("delete target refs: %w", err)
79			}
