105	// IsRefExcluded reports whether name matches any of the exclude prefixes.
106	// Empty prefixes are ignored. Used to subtract specific namespaces from
107	// auto-discovery (e.g. refs/pull/* under --all-refs against GitHub).
108	func IsRefExcluded(name plumbing.ReferenceName, excludePrefixes, excludeExact []string) bool {
109		if len(excludePrefixes) == 0 && len(excludeExact) == 0 {
110			return false
111		}
112		s := name.String()
113		for _, p := range excludePrefixes {
114			p = strings.TrimSpace(p)
115			if p == "" {
116				continue
117			}
118			if strings.HasPrefix(s, p) {
119				return true
120			}
121		}
122		// Exact names match the whole ref, so a caller can reserve
123		// refs/heads/entire without also excluding refs/heads/entire/foo — which
124		// a prefix cannot express (it would also catch refs/heads/entirely).
125		for _, e := range excludeExact {
126			if e = strings.TrimSpace(e); e != "" && s == e {
127				return true
128			}
129		}
130		return false
131	}
