183	// RefPrefixes computes the ref-prefix arguments for v2 ls-refs from cfg.
184	// Under AllRefs the result collapses to a single "refs/" prefix.
185	func RefPrefixes(cfg PlanConfig) []string {
186		if cfg.AllRefs {
187			return []string{"refs/"}
188		}
189		prefixSet := map[string]struct{}{}
190		if len(cfg.Mappings) > 0 {
191			for _, m := range cfg.Mappings {
192				src := strings.TrimSpace(m.Source)
193				switch {
194				case strings.HasPrefix(src, "refs/tags/"):
195					prefixSet["refs/tags/"] = struct{}{}
196				case strings.HasPrefix(src, "refs/heads/"):
197					prefixSet["refs/heads/"] = struct{}{}
198				case !strings.HasPrefix(src, "refs/"):
199					prefixSet["refs/heads/"] = struct{}{}
200				}
201			}
202		} else {
203			prefixSet["refs/heads/"] = struct{}{}
204		}
205		if cfg.IncludeTags {
206			prefixSet["refs/tags/"] = struct{}{}
207		}
208		prefixes := make([]string, 0, len(prefixSet))
209		for p := range prefixSet {
210			prefixes = append(prefixes, p)
211		}
212		sort.Strings(prefixes)
213		return prefixes
214	}
