41	func BuildDesiredRefs(
42		sourceRefs map[plumbing.ReferenceName]plumbing.Hash,
43		cfg PlanConfig,
44	) (map[plumbing.ReferenceName]DesiredRef, map[plumbing.ReferenceName]ManagedTarget, error) {
