52			}
53			// Reject duplicate target refs from different sources (issue #2, #3).
54			if existing, ok := desired[targetRef]; ok && existing.SourceRef != sourceRef {
55				return fmt.Errorf("duplicate target ref %s: mapped from both %s and %s", targetRef, existing.SourceRef, sourceRef)
56			}
57			short := targetRef.Short()
58			desired[targetRef] = DesiredRef{
59				Kind:       kind,
60				Label:      short,
61				SourceRef:  sourceRef,
62				TargetRef:  targetRef,
63				SourceHash: hash,
64			}
65			managed[targetRef] = ManagedTarget{Kind: kind, Label: short}
66			return nil
67		}
68	
69		if len(cfg.Mappings) > 0 {
70			// Validate all mappings up front (issue #2, #3)
71			normalized, err := validation.ValidateMappings(cfg.Mappings, cfg.AllRefs)
72			if err != nil {
73				return nil, nil, fmt.Errorf("validate ref mappings: %w", err)
74			}
75			for _, nm := range normalized {
76				kind := RefKindFromName(nm.TargetRef)
77				if err := addManaged(nm.SourceRef, nm.TargetRef, kind, sourceRefs[nm.SourceRef]); err != nil {
78					return nil, nil, err
79				}
80			}
81		} else {
82			branches := BranchMapFromRefHashMap(sourceRefs)
83			selected := SelectBranches(branches, cfg.Branches)
84			for branch, hash := range selected {
85				refName := plumbing.NewBranchReferenceName(branch)
86				if IsRefExcluded(refName, cfg.ExcludeRefPrefixes, cfg.ExcludeRefs) {
87					continue
88				}
89				if err := addManaged(refName, refName, RefKindBranch, hash); err != nil {
90					return nil, nil, err
91				}
92			}
93		}
94	
95		// AllRefs implies tag inclusion. Both passes (tag, other-kind) walk
96		// sourceRefs once: under AllRefs+IncludeTags this saves a redundant
97		// iteration on repos with thousands of refs/changes/* or refs/notes/*.
98		wantTags := cfg.IncludeTags || cfg.AllRefs
99		if wantTags || cfg.AllRefs {
100			for refName, hash := range sourceRefs {
101				kind := RefKindFromName(refName)
102				switch {
103				case kind == RefKindTag && wantTags:
104				case kind == RefKindOther && cfg.AllRefs:
105				default:
106					continue
107				}
108				if IsRefExcluded(refName, cfg.ExcludeRefPrefixes, cfg.ExcludeRefs) {
109					continue
110				}
111				if _, ok := desired[refName]; ok {
112					continue
113				}
114				if err := addManaged(refName, refName, kind, hash); err != nil {
115					return nil, nil, err
116				}
117			}
118		}
119	
120		return desired, managed, nil
121	}
